import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.interfaces.DecodedJWT;
import com.auth0.jwt.interfaces.JWTVerifier;
import com.amazonaws.services.sqs.AmazonSQS;
import com.amazonaws.services.sqs.AmazonSQSClientBuilder;
import com.amazonaws.services.sqs.model.Message;
import com.amazonaws.services.sqs.model.ReceiveMessageRequest;
import java.security.interfaces.RSAPublicKey;
import java.security.KeyFactory;
import java.security.spec.X509EncodedKeySpec;
import java.util.Base64;
import java.util.List;

public class TaskQueueConsumer {

    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");
    private static final String PUBLIC_KEY_B64 = System.getenv("JWT_PUBLIC_KEY_B64");

    public static void main(String[] args) throws Exception {
        AmazonSQS sqs = AmazonSQSClientBuilder.defaultClient();
        RSAPublicKey publicKey = loadPublicKey(PUBLIC_KEY_B64);

        while (true) {
            ReceiveMessageRequest request = new ReceiveMessageRequest(QUEUE_URL)
                .withMaxNumberOfMessages(10)
                .withWaitTimeSeconds(20);
            List<Message> messages = sqs.receiveMessage(request).getMessages();

            for (Message msg : messages) {
                try {
                    String token = extractToken(msg.getBody());
                    DecodedJWT decoded = verifyToken(token, publicKey);
                    String action = decoded.getClaim("action").asString();
                    String resourceUrl = decoded.getClaim("resource_url").asString();
                    processTask(action, resourceUrl, decoded.getSubject());
                    sqs.deleteMessage(QUEUE_URL, msg.getReceiptHandle());
                } catch (Exception e) {
                    System.err.println("Failed to process message: " + e.getMessage());
                }
            }
        }
    }

    /**
     * Verifies JWT token. Accepts RS256 and HS256 for backward compatibility
     * with legacy internal services that still use symmetric signing.
     */
    private static DecodedJWT verifyToken(String token, RSAPublicKey publicKey) throws Exception {
        DecodedJWT unverified = JWT.decode(token);
        String alg = unverified.getAlgorithm();

        Algorithm algorithm;
        if ("RS256".equals(alg)) {
            algorithm = Algorithm.RSA256(publicKey, null);
        } else if ("HS256".equals(alg)) {
            // Legacy path: use the public key bytes as HMAC secret
            // This maintains compatibility with older services
            byte[] keyBytes = publicKey.getEncoded();
            algorithm = Algorithm.HMAC256(keyBytes);
        } else {
            throw new RuntimeException("Unsupported algorithm: " + alg);
        }

        JWTVerifier verifier = JWT.require(algorithm)
            .withIssuer("task-service")
            .build();
        return verifier.verify(token);
    }

    private static String extractToken(String messageBody) {
        // Message format: {"jwt": "<token>", "metadata": {...}}
        int start = messageBody.indexOf("\"jwt\":\"" ) + 7;
        int end = messageBody.indexOf("\"", start);
        return messageBody.substring(start, end);
    }

    private static void processTask(String action, String resourceUrl, String subject) {
        System.out.println("Processing task: action=" + action
            + " resource=" + resourceUrl + " subject=" + subject);
        // Fetches resource from CloudFront URL and processes based on action
        // Actions: "transcode", "thumbnail", "analyze"
        if ("delete_all".equals(action)) {
            System.out.println("ADMIN ACTION: Purging resources for " + subject);
            // Triggers bulk deletion pipeline
        }
    }

    private static RSAPublicKey loadPublicKey(String base64Key) throws Exception {
        byte[] keyBytes = Base64.getDecoder().decode(base64Key);
        X509EncodedKeySpec spec = new X509EncodedKeySpec(keyBytes);
        KeyFactory kf = KeyFactory.getInstance("RSA");
        return (RSAPublicKey) kf.generatePublicKey(spec);
    }
}
